// Tells a player in chat when one of their key fights turns up (asked for on 2026-11-22). The rival and Team Rocket
// fights between gyms (key_fights.js, generated by tools/gen_key_trainers.py) only spawn in a few biomes and only
// one at a time, in series order, so a player could walk past the one they need without knowing. RCT spawns every
// trainer for a player (its origin player); when the trainer is one of the key fights, that player gets its name,
// distance and direction, in one of a few random lines. Each trainer is announced once (a tag on it), not again
// when its chunk loads. Trainers placed in the world (gyms, cities) are persistent and skipped, and gym leaders, the
// Elite Four and the Champion aren't in the list.

const KEY_FIGHT_ANNOUNCED = 'campfiremons_announced'
const KEY_FIGHT_DIRECTIONS = ['north', 'north-east', 'east', 'south-east', 'south', 'south-west', 'west', 'north-west']
// [one trainer, a pair like "Rocket Admins Archer & Ariana"]; {name} is the fight's name
const KEY_FIGHT_LINES = [
  ['{name} has arrived to challenge you!', '{name} have arrived to challenge you!'],
  ['{name} has come looking for a battle!', '{name} have come looking for a battle!'],
  ['{name} has tracked you down!', '{name} have tracked you down!'],
  ['{name} is on your trail!', '{name} are on your trail!'],
  ['{name} wants to battle you!', '{name} want to battle you!'],
  ['A challenger approaches: {name}!', 'Challengers approach: {name}!'],
]

EntityEvents.spawned('rctmod:trainer', event => {
  let trainer = event.entity
  if (trainer.getTags().contains(KEY_FIGHT_ANNOUNCED)) return
  // A tick later: RCT may set the origin player after the trainer joins the level
  event.level.server.scheduleInTicks(1, () => announceKeyFight(trainer))
})

function keyFightOf(id) {
  let fights = KEY_FIGHTS
  for (let i = 0; i < fights.length; i++) {
    if (fights[i].ids.indexOf(id) >= 0) return fights[i]
  }
  return null
}

function announceKeyFight(trainer) {
  if (!trainer.isAlive() || trainer.isPersistenceRequired()) return
  let fight = keyFightOf(String(trainer.getTrainerId()))
  let uuid = fight ? trainer.getOriginPlayer() : null
  if (!uuid) return
  trainer.addTag(KEY_FIGHT_ANNOUNCED)
  let player = trainer.level.server.getPlayerList().getPlayer(uuid)
  console.info(`[campfiremons] key fight ${fight.name} (Lv${fight.level}) spawned for ${player ? player.username : uuid}`)
  if (player && player.level == trainer.level) {
    let msg = keyFightMessage(player, trainer, fight)
    player.tell(Text.gold(msg[0]).append(Text.gray(' ' + msg[1])))
  }
}

// ["Rocket Admin Archer has arrived to challenge you!", "(about 40 blocks north-east)"]
function keyFightMessage(player, trainer, fight) {
  let dx = trainer.x - player.x
  let dz = trainer.z - player.z
  let distance = Math.round(Math.sqrt(dx * dx + dz * dz))
  let bearing = Math.atan2(dx, -dz) * 180 / Math.PI // 0 = north (-z), 90 = east (+x)
  let direction = KEY_FIGHT_DIRECTIONS[((Math.round(bearing / 45) % 8) + 8) % 8]
  let line = KEY_FIGHT_LINES[Math.floor(Math.random() * KEY_FIGHT_LINES.length)][fight.name.indexOf(' & ') >= 0 ? 1 : 0]
  return [line.replace('{name}', fight.name), `(about ${distance} blocks ${direction})`]
}
